"""Navigation icons cropped from the user's August 2026 inventory captures."""

from base64 import b64decode

import cv2
import numpy as np

_PNG = {
    "stash_frame": "",
    "equipment": "",
    "talisman": "",
    "socketables": "",
    "consumables": "",
    "keys": "",
    "stash": "",
}


def icon(name: str) -> np.ndarray:
    result = cv2.imdecode(np.frombuffer(b64decode(_PNG[name]), dtype=np.uint8), cv2.IMREAD_GRAYSCALE)
    if result is None:
        msg = f"Embedded inventory navigation icon is invalid: {name}"
        raise ValueError(msg)
    return result
